"""Cuaderno del estudiante, 1.º básico Lenguaje y Comunicación, OA 03 (conciencia fonológica) y OA 04 (lectura de palabras)."""
from __future__ import annotations

from student_lessons import ex, register

OA3, OA4 = "LE01 OA 03", "LE01 OA 04"


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, context, selfcheck, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=context, selfcheck=selfcheck, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


